import contextlib,dataclasses,io,json,sys,types
p=Path.cwd()/"checks/independent/dfm-electroweak-continuum-fence.py"
s=p.read_text(encoding="utf-8")
if len(sys.argv)>1:
 changes={"conjugation":("return GR(self.re, -self.im)","return GR(self.re, self.im)"),"mutable_value":("frozen=True","frozen=False")}
 a,b=changes[sys.argv[1]]
 if s.count(a)!=1: raise RuntimeError("mutation match")
 s=s.replace(a,b,1)
m=types.ModuleType("pr230_checker"); m.__file__=str(p); sys.modules[m.__name__]=m; exec(compile(s,str(p),"exec"),m.__dict__)
m.main()
controls=[]
def refuse(label,call,exc):
 try: call()
 except exc: controls.append(label); return
 raise RuntimeError("accepted invalid control: "+label)
for label,value in [("float",0.5),("bool",True),("str","1"),("complex",1j),("None",None),("object",object())]:
 refuse("construct_"+label,lambda value=value:m.GR(value),(TypeError,))
refuse("zero_denominator",lambda:m.GR(1).div(0),(ValueError,))
refuse("float_denominator",lambda:m.GR(1).div(0.5),(TypeError,))
refuse("bool_denominator",lambda:m.GR(1).div(True),(TypeError,))
for attr in ("re","im"):
 refuse("assign_"+attr,lambda attr=attr:setattr(m.GR(1),attr,0.5),(dataclasses.FrozenInstanceError,))
if m.GR(1)==object(): raise RuntimeError("unrelated equality")
print(json.dumps({"refusals":controls,"count":len(controls),"unrelated_equality":False}))

