import json
import sympy as S
A,B,C,D,E,F=S.symbols('a b c d e f',rational=True); den=S.symbols('s',rational=True,nonzero=True)
z=A+S.I*B; p=C+S.I*D; q=E+S.I*F

def u(x,y): return S.Matrix([[S.conjugate(y),x],[-S.conjugate(x),y]])
def norm(x): return S.expand(x*S.conjugate(x))
def zeros(m):
 values=[S.simplify(S.expand(x)) for x in m]
 if any(x!=0 for x in values): raise RuntimeError(values)
 return [str(x) for x in values]
result={'unnormalized_four_entries':zeros(u(z*p,z*q)-u(p,q)*S.diag(S.conjugate(z),z)),'shared_nonzero_denominator_four_entries':zeros(u(z*p,z*q)/den-u(p,q)/den*S.diag(S.conjugate(z),z))}
res=S.expand(norm(z*p)+norm(z*q)-norm(z)*(norm(p)+norm(q)))
if res!=0: raise RuntimeError(res)
result['norm_multiplicativity_residual']=str(res)
zu=S.Rational(3,5)+S.I*S.Rational(4,5)
if norm(zu)!=1 or u(zu,0)[0,1]!=zu: raise RuntimeError('unit witness')
left=(u(2,0)/2)[0,1]; right=(u(1,0)*S.diag(2,2))[0,1]
if left!=1 or right!=2 or left==right: raise RuntimeError('nonunit split')
result.update(unit_norm=str(norm(zu)),unit_entry=str(zu),nonunit_own_root_entries=[str(left),str(right)],scope='Independent SymPy component identities; symbolic denominator nonzero. Lean total division at zero is a separate boundary, and the executable checker refuses zero. No repository imports.')
print(json.dumps(result,indent=2))
